// Violates Symmetry or Transitivity when subclassing with a new value field!
public class Point {
    private final int x, y;
    public Point(int x, int y) { this.x = x; this.y = y; }

    @Override public boolean equals(Object o) {
        if (!(o instanceof Point)) return false;
        Point p = (Point) o;
        return p.x == x && p.y == y;
    }
}

public class ColorPoint extends Point {
    private final String color;
    public ColorPoint(int x, int y, String color) {
        super(x, y);
        this.color = color;
    }

    // Attempting mixed comparisons violates symmetry or transitivity!
    @Override public boolean equals(Object o) {
        if (!(o instanceof Point)) return false;
        // If o is a normal Point, ignore color — VIOLATES TRANSITIVITY!
        if (!(o instanceof ColorPoint))
            return o.equals(this);
        return super.equals(o) && ((ColorPoint) o).color.equals(color);
    }
}

