// Favor composition over inheritance: give ColorPoint a private Point field
import java.util.Objects;

public class ColorPoint {
    private final Point point;
    private final String color;

    public ColorPoint(int x, int y, String color) {
        this.point = new Point(x, y);
        this.color = Objects.requireNonNull(color);
    }

    public Point asPoint() { return point; }

    @Override public boolean equals(Object o) {
        if (this == o) return true; // Performance optimization
        if (!(o instanceof ColorPoint)) return false; // Non-nullity & type check
        ColorPoint cp = (ColorPoint) o;
        return cp.point.equals(point) && cp.color.equals(color);
    }

    @Override public int hashCode() {
        return Objects.hash(point, color);
    }
}

