public class Main {
    public static void main(String[] args) {
        ColorPoint cp1 = new ColorPoint(1, 2, "red");
        ColorPoint cp2 = new ColorPoint(1, 2, "red");
        Point p = new Point(1, 2);

        System.out.println(cp1.equals(cp2)); // true (consistent & transitive)
        System.out.println(cp1.equals(p));   // false (preserves symmetry!)
    }
}
